<?php
namespace App\Core; abstract class Controller{protected function view(string $view,array $data=[]):void{extract($data);$app=require __DIR__.'/../../config/app.php';$viewFile=__DIR__.'/../Views/'.$view.'.php';require __DIR__.'/../Views/layouts/app.php';} protected function json(array $data,int $status=200):void{http_response_code($status);header('Content-Type: application/json; charset=utf-8');echo json_encode($data,JSON_UNESCAPED_UNICODE);exit;} protected function input():array{return json_decode(file_get_contents('php://input'),true) ?: $_POST;} protected function requireCsrf():void{if(($_SERVER['REQUEST_METHOD']??'GET')!=='GET' && !Csrf::verify($_POST['_token']??($_SERVER['HTTP_X_CSRF_TOKEN']??''))){$this->json(['ok'=>false,'message'=>'توکن امنیتی نامعتبر است.'],419);}}}
